function supplierVerticalCapabilityState(snapshot,vertical){const caps=(snapshot?.capabilities||[]).filter(x=>x.vertical===vertical),cert=(snapshot?.certifications||[]).find(x=>x.vertical===vertical),required=['SEARCH','DETAIL','QUOTE','REVALIDATE','ORDER','CANCEL','REFUND','RECONCILIATION'];return {caps,cert,certified:cert?.state==='PASS_CONTRACT_ONLY'&&required.every(key=>caps.some(x=>x.capability===key&&x.state==='CERTIFIED_CONTRACT_ONLY')),externalLive:snapshot?.external_live===true}}
async function supplierVerticalSnapshot(){try{return unwrap(await api.request('/v1/supplier/verticals'))||{capabilities:[],certifications:[],external_live:false}}catch(error){return {capabilities:[],certifications:[],external_live:false,error:String(error?.message||error)}}}
function supplierVerticalTasks(vertical){const item=SUPPLIER_NONHOTEL_VERTICALS[vertical];return [['运营与供给',`${item.label}可售供给、报价与状态。`,'/operations-hub'],['订单与履约',`${item.label}订单确认与履约处理。`,'/orders'],['取消与退款',`${item.label}取消、退款和规则事实。`,'/refunds'],['异常与恢复',`${item.label}异常、恢复和人工处理。`,'/supplier-exception-center'],['证据与对账',`${item.label}交易证据、差异与对账。`,'/reconciliation'],['连接器 / Provider',`仅显示已配置、已认证的 ${item.label} 连接能力。`,'/connectors']]}
async function supplierVerticals(){currentSupplierRoute='/vertical-capabilities';const snapshot=await supplierVerticalSnapshot(),cards=Object.entries(SUPPLIER_NONHOTEL_VERTICALS).map(([vertical,item])=>{const state=supplierVerticalCapabilityState(snapshot,vertical),status=state.certified?'已认证（合同级）':'未认证 / 不可执行',detail=state.certified?`${state.caps.length} 项能力已通过合同级认证；外部真实执行：${state.externalLive?'已启用':'未启用'}`:'未完成能力认证或 Provider 未就绪；系统保持 fail-closed，不产生模拟外部执行。';return supplierHubCard(item.label,detail,item.route,status)}),error=snapshot.error?`<section class="card structured-section"><div><h3>能力状态暂不可读取</h3><p>${esc(snapshot.error)}</p></div><span class="status">保持关闭</span></section>`:'';$('#view').innerHTML=`<div class="section-head structured-head"><div><h2>全品类能力</h2><span>供应商主体的能力、认证与连接状态决定可进入的任务；未认证时不模拟外部 Provider。</span></div><span class="status">合同级门禁</span></div>${error}<div class="grid supplier-hub-grid">${cards.join('')}</div>`}
async function supplierVerticalTaskShell(route){const vertical=Object.entries(SUPPLIER_NONHOTEL_VERTICALS).find(([,item])=>item.route===route)?.[0];if(!vertical)return supplierPlaceholder('/vertical-capabilities',['业务品类能力']);const item=SUPPLIER_NONHOTEL_VERTICALS[vertical],snapshot=await supplierVerticalSnapshot(),state=supplierVerticalCapabilityState(snapshot,vertical),readiness=state.certified?'合同级能力已认证；真实外部 Provider 仍需单独启用。':'当前未达到执行条件；不显示虚假订单、报价、履约或外部 Provider 成功状态。',cards=supplierVerticalTasks(vertical).map(task=>supplierHubCard(...task));$('#view').innerHTML=`<div class="section-head structured-head"><div><h2>${esc(item.label)}业务任务</h2><span>${esc(readiness)}</span></div><span class="status">${state.certified?'合同级就绪':'Fail-closed'}</span></div><section class="card structured-section"><div><h3>当前认证事实</h3><p>能力项：${state.caps.length}；认证：${esc(state.cert?.state||'未认证')}；外部真实执行：${state.externalLive?'已启用':'未启用'}。</p></div><a class="btn" href="#/connectors">查看连接器</a></section><div class="grid supplier-hub-grid">${cards.join('')}</div>`}
