const labelize=k=>{const raw=String(k),tail=raw.split('.').pop();if(config?.actorType==='GO_ADMIN')return adminFriendlyLabel(k);return OPERATING_LABELS[raw]||OPERATING_LABELS[tail]||raw.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase())};
function friendlyValue(v){const m={PUBLISHED_REQUEST_ONLY:'预订申请模式',SANDBOX_APPLICATION_NOT_CREATED:'支付宝测试环境尚未开通',true:'已启用',false:'未启用'};const x=m[String(v)]??v;return config?.actorType==='GO_ADMIN'?(ADMIN_STATE_LABELS[String(x)]??x):x}
function loginView(){document.body.innerHTML=`<main class="login-screen"><form class="login-card" id="login"><h1>${esc(config.title)}</h1><p>${esc(config.subtitle)}</p><div class="field"><label>用户名</label><input id="user" required value="${esc(config.demoUser||'')}"></div><div class="field"><label>密码</label><input id="pass" type="password" required></div><div class="field"><label>MFA 动态码（已绑定账号填写）</label><input id="totp" inputmode="numeric" autocomplete="one-time-code" maxlength="6"></div>${config.actorType==='GO_ADMIN'?'<div class="notice" id="adminMfaPolicy">正在读取当前环境 MFA 策略…</div>':''}<div id="loginErr"></div><button class="btn primary">安全登录</button>${config.actorType==='GO_ADMIN'?'<a class="btn sso-login" href="/bff/auth/sso/start">企业 SSO 登录</a>':''}${config.actorType==='SUPPLIER_USER'?'<button class="btn" type="button" id="supplierRegisterStart">申请成为 GO 合作伙伴</button>':''}</form></main>`;if(config.actorType==='GO_ADMIN')loadAdminMfaPolicy();$('#login').onsubmit=async e=>{e.preventDefault();const username=$('#user').value,password=$('#pass').value,totp=$('#totp').value||null;try{me=unwrap(await api.login(username,password,totp));if(config.actorType&&me.actor_type!==config.actorType)throw new Error('账号类型不匹配');shell()}catch(err){if(config.actorType==='GO_ADMIN'&&err.message==='MFA_ENROLLMENT_REQUIRED'){try{const enroll=unwrap(await api.startMfaEnrollment(username,password));mfaEnrollmentView(enroll)}catch(startErr){$('#loginErr').innerHTML=`<div class="notice error">${esc(userFacingError(startErr.message))}</div>`}}else{$('#loginErr').innerHTML=`<div class="notice error">${esc(userFacingError(err.message))}</div>`}}};if($('#supplierRegisterStart'))$('#supplierRegisterStart').onclick=supplierRegisterView}
async function supplierRegisterView(){let terms;try{terms=unwrap(await api.supplierRegistrationTerms())}catch(e){notice(userFacingError(e.message),true);return}const versions=terms.versions||{};document.body.innerHTML=`<main class="login-screen"><form class="login-card" id="supplierRegister"><h1>GO 合作伙伴入驻</h1><p>创建企业账号并一次性签署当前版本平台条款；随后进入主体核验与对应业务能力开通。创建账号不代表已审核或已开通交易。</p><div class="field"><label>企业 / 酒店主体名称</label><input id="org" required></div><div class="field"><label>联系人姓名</label><input id="contact" required></div><div class="field"><label>邮箱</label><input id="regEmail" type="email" required></div><div class="field"><label>手机号</label><input id="regPhone" type="tel"></div><div class="field"><label>设置密码</label><input id="regPass" type="password" minlength="10" required></div><section class="card"><h3>合作伙伴协议与平台规则一次性签署</h3>${Object.entries(terms.titles||{}).map(([k,v])=>`<div class="kv"><span>${esc(v)}</span><b>${esc(versions[k]||'当前版本')}</b></div>`).join('')}<label style="display:flex;gap:8px;align-items:flex-start;margin-top:12px"><input id="acceptTerms" type="checkbox" required><span>我已阅读并同意以上当前版本条款，并同意以电子方式完成本次签署。后续条款重大变更按规则另行提示。</span></label></section><div id="supplierRegisterErr"></div><button class="btn primary">提交入驻申请</button><button class="btn" type="button" id="supplierRegisterBack">返回登录</button></form></main>`;$('#supplierRegisterBack').onclick=loginView;$('#supplierRegister').onsubmit=async e=>{e.preventDefault();try{me=unwrap(await api.supplierRegister({email:$('#regEmail').value,password:$('#regPass').value,organization_name:$('#org').value,contact_name:$('#contact').value,phone:$('#regPhone').value||null,accepted_terms:$('#acceptTerms').checked,term_versions:versions}));if(me.actor_type!=='SUPPLIER_USER')throw new Error('账号类型不匹配');shell()}catch(err){$('#supplierRegisterErr').innerHTML=`<div class="notice error">${esc(userFacingError(err.message))}</div>`}}}

async function loadAdminMfaPolicy(){const n=$('#adminMfaPolicy');if(!n)return;try{const p=unwrap(await api.authPolicy());n.textContent=p.admin_mfa_required?'当前环境已启用管理端 MFA。首次登录将进入 MFA 绑定流程；已绑定账号需填写 6 位动态码。':'当前环境暂未强制 MFA。测试期间可使用用户名和密码登录；正式启用后将要求完成 MFA 绑定与动态码验证。'}catch{n.textContent='当前 MFA 状态以服务器运行配置为准。'}}
function mfaEnrollmentView(enroll){document.body.innerHTML=`<main class="login-screen"><form class="login-card" id="mfaEnroll"><h1>首次 MFA 绑定</h1><p>请在 Microsoft Authenticator、Google Authenticator、1Password 等 TOTP 应用中添加账号，然后输入当前 6 位动态码完成绑定。</p><div class="card mfa-setup-card"><div class="field"><label>设置密钥</label><div class="mono mfa-secret">${esc(enroll.secret)}</div></div><div class="field"><label>Authenticator URI</label><div class="mono mfa-uri">${esc(enroll.provisioning_uri)}</div></div><p class="muted">此绑定令牌仅用于 MFA 设置，约 ${Math.ceil((enroll.expires_in||600)/60)} 分钟后失效，不能访问任何管理功能。</p></div><div class="field"><label>6 位动态码</label><input id="mfaCode" inputmode="numeric" autocomplete="one-time-code" maxlength="6" pattern="[0-9]{6}" required></div><div id="mfaErr"></div><button class="btn primary">确认绑定并登录</button><button class="btn" type="button" id="mfaBack">返回登录</button></form></main>`;$('#mfaBack').onclick=loginView;$('#mfaEnroll').onsubmit=async e=>{e.preventDefault();try{me=unwrap(await api.confirmMfaEnrollment(enroll.enrollment_token,$('#mfaCode').value));if(config.actorType&&me.actor_type!==config.actorType)throw new Error('账号类型不匹配');shell()}catch(err){$('#mfaErr').innerHTML=`<div class="notice error">${esc(userFacingError(err.message))}</div>`}}}

function supplierMobileChrome(){if(config.actorType!=='SUPPLIER_USER')return '';const items=[['/command','首页','⌂'],['/operations-hub','履约','▤'],['/marketing-rights','促销权益','◇'],['/finance-hub','财务','¥']];return `<nav class="supplier-mobile-bottom" aria-label="供应商移动端主导航">${items.map(([r,l,i])=>`<a href="#${r}" data-mobile-route="${r}"><span class="supplier-mobile-icon">${i}</span><span>${l}</span></a>`).join('')}<button type="button" id="supplierMobileMore"><span class="supplier-mobile-icon">☰</span><span>我的</span></button></nav><div class="supplier-mobile-sheet hidden" id="supplierMobileSheet"><button class="supplier-mobile-backdrop" id="supplierMobileClose" aria-label="关闭"></button><section class="supplier-mobile-sheet-card"><div class="supplier-mobile-sheet-head"><div><strong>${esc(config.title)}</strong><small>${esc(me.username)}</small></div><button class="btn" id="supplierMobileClose2">关闭</button></div><div class="supplier-mobile-function-grid">${nav.map(x=>`<a href="#${x.route}" data-mobile-menu-route="${x.route}">${esc(x.label)}</a>`).join('')}</div><button class="btn supplier-mobile-logout" id="supplierMobileLogout">退出登录</button></section></div>`} 
function bindSupplierMobileChrome(){if(config.actorType!=='SUPPLIER_USER')return;const sheet=$('#supplierMobileSheet'),open=$('#supplierMobileMore'),close=()=>sheet?.classList.add('hidden');if(open)open.onclick=()=>sheet?.classList.remove('hidden');$('#supplierMobileClose')?.addEventListener('click',close);$('#supplierMobileClose2')?.addEventListener('click',close);document.querySelectorAll('[data-mobile-menu-route]').forEach(a=>a.addEventListener('click',close));$('#supplierMobileLogout')?.addEventListener('click',async()=>{await api.logout();loginView()})}
function adminMobileChrome(){if(config.actorType!=='GO_ADMIN')return '';const items=config.mobileNav||[];return `<nav class="admin-mobile-bottom" aria-label="管理端移动主导航">${items.map(x=>`<a href="#${x.route}" data-admin-mobile-route="${x.route}"><span class="admin-mobile-icon">${x.icon||'•'}</span><span>${esc(x.label)}</span></a>`).join('')}<button type="button" id="adminMobileMore"><span class="admin-mobile-icon">☰</span><span>全部</span></button></nav><div class="admin-mobile-sheet hidden" id="adminMobileSheet"><button class="admin-mobile-backdrop" id="adminMobileClose" aria-label="关闭"></button><section class="admin-mobile-sheet-card"><div class="admin-mobile-sheet-head"><div><strong>${esc(config.title)}</strong><small>${esc(me.username)}</small></div><button class="btn" id="adminMobileClose2">关闭</button></div><div class="admin-mobile-function-grid">${nav.map(x=>`<a href="#${x.route}" data-admin-menu-route="${x.route}">${esc(x.label)}</a>`).join('')}</div><button class="btn admin-mobile-logout" id="adminMobileLogout">退出登录</button></section></div>`}
function bindAdminMobileChrome(){if(config.actorType!=='GO_ADMIN')return;const sheet=$('#adminMobileSheet'),close=()=>sheet?.classList.add('hidden');$('#adminMobileMore')?.addEventListener('click',()=>sheet?.classList.remove('hidden'));$('#adminMobileClose')?.addEventListener('click',close);$('#adminMobileClose2')?.addEventListener('click',close);document.querySelectorAll('[data-admin-menu-route]').forEach(a=>a.addEventListener('click',close));$('#adminMobileLogout')?.addEventListener('click',async()=>{await api.logout();loginView()})}
function shell(){document.body.innerHTML=`<div class="shell ${config.actorType==='SUPPLIER_USER'?'supplier-shell':''} ${config.actorType==='GO_ADMIN'?'admin-shell':''}"><aside class="sidebar"><div class="brand go-brand-lockup"><span class="go-brand-g">G</span><i></i><span class="go-brand-o">O</span></div><div class="subbrand">${esc(config.title)}</div><nav class="nav">${nav.map(x=>`<a href="#${x.route}" data-route="${x.route}">${esc(x.label)}</a>`).join('')}</nav><div class="sidebar-footer">${esc(me.username)}<br>${esc((me.roles||[]).join(', '))}</div></aside><main class="main"><header class="topbar"><div class="title" id="pageTitle"></div><div class="actor"><span class="badge">${esc(me.actor_type)}</span><button id="logout" class="btn">退出</button></div></header><div class="content"><div id="notice"></div><div id="view"></div></div></main>${supplierMobileChrome()}${adminMobileChrome()}</div>`;$('#logout').onclick=async()=>{await api.logout();loginView()};bindSupplierMobileChrome();bindAdminMobileChrome();window.addEventListener('hashchange',route);route()}
function notice(msg,bad=false){$('#notice').innerHTML=msg?`<div class="notice ${bad?'error':''}">${esc(msg)}</div>`:''}
function consoleCloseSheet(){document.querySelector('.console-sheet-backdrop')?.remove()}
function consoleSheet({title,description='',fields=[],confirmLabel='确认',danger=false,onConfirm}){consoleCloseSheet();const wrap=document.createElement('div');wrap.className='console-sheet-backdrop';wrap.innerHTML=`<section class="console-sheet" role="dialog" aria-modal="true" aria-labelledby="consoleSheetTitle"><div class="console-sheet-handle"></div><h2 id="consoleSheetTitle">${esc(title)}</h2>${description?`<p>${esc(description)}</p>`:''}<div class="console-sheet-fields">${fields.map(f=>`<div class="field"><label for="${esc(f.id)}">${esc(f.label)}</label><input id="${esc(f.id)}" type="${esc(f.type||'text')}" value="${esc(f.value||'')}" placeholder="${esc(f.placeholder||'')}" ${f.required===false?'':'required'}></div>`).join('')}</div><div class="console-sheet-actions"><button class="btn" id="consoleSheetCancel">取消</button><button class="btn ${danger?'danger':'primary'}" id="consoleSheetConfirm">${esc(confirmLabel)}</button></div></section>`;document.body.appendChild(wrap);setTimeout(()=>wrap.querySelector('input')?.focus(),0);wrap.querySelector('#consoleSheetCancel').onclick=consoleCloseSheet;wrap.onclick=e=>{if(e.target===wrap)consoleCloseSheet()};wrap.querySelector('#consoleSheetConfirm').onclick=async()=>{const values={};for(const f of fields){const el=wrap.querySelector('#'+CSS.escape(f.id));if(f.required!==false&&!el.value.trim()){notice(`请填写${f.label}`,true);el.focus();return}values[f.id]=el.value.trim()}const b=wrap.querySelector('#consoleSheetConfirm');b.disabled=true;b.textContent='处理中…';try{await onConfirm?.(values);consoleCloseSheet()}catch(e){notice(e.message,true);b.disabled=false;b.textContent=confirmLabel}}}
function consoleConfirm({title,description='',confirmLabel='确认',danger=false,onConfirm}){return consoleSheet({title,description,fields:[],confirmLabel,danger,onConfirm})}
function cell(k,v){if(v==null)return '—';if(/amount_minor|value_minor|balance_minor|refund_minor|compensation_minor|total_minor/i.test(k)&&typeof v==='number')return money(v);if(/status|state|health/i.test(k))return `<span class="status ${statusClass(String(v))}">${esc(config.actorType==='SUPPLIER_USER'?supplierFriendlyValue(v):friendlyValue(v))}</span>`;if(typeof v==='object')return config.actorType==='SUPPLIER_USER'?'查看详情':(config.actorType==='GO_ADMIN'?'查看详情':`<span class="mono clamp">${esc(JSON.stringify(v))}</span>`);return esc(config.actorType==='SUPPLIER_USER'?supplierFriendlyValue(v):(config.actorType==='GO_ADMIN'?adminFriendlyValue(v):v))}
function table(data,onClick=null,emptyTitle='当前数据'){const arr=Array.isArray(data)?data:(data?.items||data?.results||[]);if(!arr.length)return config.actorType==='SUPPLIER_USER'?supplierStructuredEmpty(currentSupplierRoute,emptyTitle):(config.actorType==='GO_ADMIN'?adminEmpty(emptyTitle):'<div class="table-wrap"><div class="empty">暂无数据</div></div>');let cols=Array.from(new Set(arr.flatMap(x=>Object.keys(x||{})))).filter(x=>!['metadata','payload','request_payload'].includes(x));if(config.actorType==='SUPPLIER_USER')cols=cols.filter(x=>!/(secret|token|fingerprint|hash|raw_|request_payload|provider_payload)/i.test(x));cols=cols.slice(0,9);return `<div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${esc(config.actorType==='SUPPLIER_USER'?supplierFriendlyLabel(c):labelize(c))}</th>`).join('')}</tr></thead><tbody>${arr.map((r,i)=>`<tr ${onClick?`class="clickable" data-i="${i}"`:''}>${cols.map(c=>`<td data-label="${esc(config.actorType==='SUPPLIER_USER'?supplierFriendlyLabel(c):labelize(c))}">${cell(c,r[c])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${onClick?`<script type="application/json" id="rowData">${esc(JSON.stringify(arr))}</script>`:''}`}
function bindRows(arr,fn){document.querySelectorAll('tr[data-i]').forEach(tr=>tr.onclick=()=>fn(arr[Number(tr.dataset.i)]))}
function metrics(data){const flat=[];for(const [k,v] of Object.entries(data||{})){if(typeof v==='number'||typeof v==='string')flat.push([k,v]);else if(v&&typeof v==='object'&&!Array.isArray(v))for(const [a,b] of Object.entries(v))if(typeof b==='number'||typeof b==='string')flat.push([`${k}.${a}`,b])}return `<div class="grid">${flat.slice(0,12).map(([k,v])=>`<div class="card"><div class="metric-label">${esc(labelize(k))}</div><div class="metric-value">${typeof v==='number'?v:esc(friendlyValue(v))}</div></div>`).join('')}</div>`}
function jsonCard(title,obj){return `<details class="card tech-diagnostics"><summary>${esc(title)} · 技术信息</summary><pre class="mono pre">${esc(JSON.stringify(obj,null,2))}</pre></details>`}
function supplierObjectCard(title,obj){const entries=Object.entries(obj||{}).filter(([k])=>!/(secret|token|fingerprint|hash|raw_|payload|metadata)/i.test(k)).slice(0,12);if(!entries.length)return supplierStructuredEmpty(currentSupplierRoute,title);return `<section class="card"><h3>${esc(title)}</h3><div class="kv">${entries.map(([k,v])=>`<div>${esc(supplierFriendlyLabel(k))}</div><div>${esc(typeof v==='object'?'查看结构化子项':supplierFriendlyValue(v))}</div>`).join('')}</div></section>`}
async function generic(item){$('#view').innerHTML='<div class="card">加载中...</div>';try{const r=unwrap(await api.request(item.endpoint));const rendered=item.kind==='dashboard'?metrics(r):table(r);$('#view').innerHTML=`<section class="productized-admin-head"><div><h2>${esc(item.label)}</h2><p>当前状态 → 核心指标 → 业务对象 → 待办异常 → 可执行动作 → 状态与审计</p></div><span class="status">运营工作台</span></section>${rendered}${adminOpsBar()}${jsonCard('技术信息 / 原始运行事实',r)}`;adminProductizeView(item.route,item.label);bindAdminOps()}catch(e){notice(e.message,true)}}
async function supplierOrders(){const data=unwrap(await api.request('/v1/supplier/orders'));const arr=data.items||[];const body=table(arr,true,'订单');$('#view').innerHTML=supplierStructuredShell('/orders',body,{'待确认':arr.filter(x=>String(x.state||x.status).includes('PENDING')).length,'已确认':arr.filter(x=>String(x.state||x.status).includes('CONFIRMED')).length,'履约中':arr.filter(x=>String(x.state||x.status).includes('STAY')).length,'售后中':arr.filter(x=>/CANCEL|REFUND/.test(String(x.state||x.status))).length});bindRows(arr,r=>orderWorkbench(r.order_id))}
async function orderWorkbench(id){const d=unwrap(await api.request(`/v1/supplier/orders/${encodeURIComponent(id)}/workbench`));currentSupplierRoute='/orders';$('#view').innerHTML=`<button class="btn" id="back">← 返回订单</button><div class="section-head"><div><h2>订单详情</h2><span>订单事实、退改、支付、退款与事件时间线</span></div><span class="status">${esc(supplierFriendlyValue(d.order?.state||d.order?.status||'待处理'))}</span></div>${supplierObjectCard('订单事实',d.order)}<section class="card structured-section"><div><h3>退改政策</h3><p>取消、改期和费用均以订单快照与当前可执行报价为准。</p></div><span class="status">规则已结构化</span></section><div class="actionbar"><button class="btn primary" id="cancelQuote">生成取消报价</button><button class="btn" id="changeQuote">改期报价</button></div><div id="actionResult"></div><h3>支付</h3>${table(d.payments,false,'支付记录')}<h3>退款</h3>${table(d.refunds,false,'退款记录')}<h3>改期</h3>${table(d.changes,false,'改期记录')}<h3>住宿额度</h3>${table(d.stay_credits,false,'住宿额度')}<h3>事件时间线</h3>${table(d.timeline,false,'订单事件')}`;$('#back').onclick=supplierOrders;$('#cancelQuote').onclick=async()=>{try{const q=unwrap(await api.request(`/v1/supplier/orders/${id}/cancellation-quote`,{method:'POST'}));$('#actionResult').innerHTML=supplierObjectCard('取消报价',q)+`<button class="btn danger" id="execCancel">确认执行取消</button>`;$('#execCancel').onclick=async()=>{await api.request(`/v1/supplier/orders/${id}/cancel`,{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:{cancellation_quote_id:q.quote_id}});notice('取消流程已执行');orderWorkbench(id)}}catch(e){notice(e.message,true)}};$('#changeQuote').onclick=()=>consoleSheet({title:'生成改期报价',description:'填写新的入住和退房日期，先看报价再执行。',fields:[{id:'consoleCheckIn',label:'新入住日期',type:'date'},{id:'consoleCheckOut',label:'新退房日期',type:'date'}],confirmLabel:'生成报价',onConfirm:async v=>{const q=unwrap(await api.request(`/v1/supplier/orders/${id}/change-quote`,{method:'POST',body:{new_check_in:v.consoleCheckIn,new_check_out:v.consoleCheckOut}}));$('#actionResult').innerHTML=supplierObjectCard('改期报价',q)+`<button class="btn primary" id="execChange">确认改期</button>`;$('#execChange').onclick=async()=>{await api.request(`/v1/supplier/orders/${id}/change`,{method:'POST',body:{change_quote_id:q.change_quote_id,payment_method_token:'pm_console'}});notice('改期流程已执行');orderWorkbench(id)}}})}
async function supplierRisks(){const d=unwrap(await api.request('/v1/supplier/risk-cases'));const arr=d.items||[];$('#view').innerHTML=`<div class="section-head"><h2>Risk Case 工作台</h2></div>${table(arr,true)}`;bindRows(arr,r=>riskWorkbench(r.risk_event_id))}
async function riskWorkbench(id){const d=unwrap(await api.request(`/v1/supplier/risk-cases/${id}/workbench`));$('#view').innerHTML=`<button class="btn" id="back">← 返回风险事件</button><div class="split">${jsonCard('风险事实',d.risk)}${jsonCard('证据统计',{evidence:d.evidence.length,remediation:d.remediation.length})}</div><div class="actionbar"><button class="btn primary" id="evidence">提交补证</button><button class="btn" id="remed">提交整改</button></div><h2>Evidence</h2>${table(d.evidence)}<h2>Remediation</h2>${table(d.remediation)}`;$('#back').onclick=supplierRisks;$('#evidence').onclick=()=>consoleSheet({title:'提交补证',fields:[{id:'evidenceType',label:'证据类型',value:'HOUSEKEEPING_RECORD'},{id:'contentRef',label:'文件引用（可空）',required:false}],confirmLabel:'提交证据',onConfirm:async v=>{await api.request(`/v1/supplier/risk-cases/${id}/evidence`,{method:'POST',body:{evidence_type:v.evidenceType,payload:{note:'Supplier Console submission'},content_ref:v.contentRef||null}});notice('证据已提交');riskWorkbench(id)}});$('#remed').onclick=()=>consoleSheet({title:'提交整改',fields:[{id:'remediationAction',label:'整改动作',value:'DEEP_CLEANING_COMPLETED'}],confirmLabel:'提交整改',onConfirm:async v=>{await api.request(`/v1/supplier/risk-cases/${id}/remediation`,{method:'POST',body:{action:v.remediationAction,evidence_ids:[]}});notice('整改已提交');riskWorkbench(id)}})}
async function supplierLiabilities(){const d=unwrap(await api.request('/v1/supplier/liabilities'));const arr=d.items||[];$('#view').innerHTML=`<div class="section-head"><h2>赔付责任</h2></div>${table(arr,true)}`;bindRows(arr,r=>liabilityWorkbench(r.liability_id))}
async function liabilityWorkbench(id){const d=unwrap(await api.request(`/v1/supplier/liabilities/${id}/workbench`));$('#view').innerHTML=`<button class="btn" id="back">← 返回赔付责任</button><div class="split">${jsonCard('Liability',d.liability)}${jsonCard('Fault Case',d.fault_case)}</div><h2>赔付支付</h2>${table(d.compensation_payments)}`;$('#back').onclick=supplierLiabilities}
async function adminJudgments(){const d=unwrap(await api.request('/internal/v1/admin/judgments'));const arr=d.items||[];$('#view').innerHTML=`<div class="section-head"><h2>GO 判断 / Evidence Replay</h2></div>${table(arr,true)}`;bindRows(arr,r=>judgmentReplay(r.judgment_id))}
async function judgmentReplay(id){const d=unwrap(await api.request(`/internal/v1/admin/judgments/${id}/evidence-replay`));$('#view').innerHTML=`<button class="btn" id="back">← 返回 Judgment</button><div class="split">${jsonCard('Judgment',d.judgment)}${jsonCard('Recommendation',d.recommendation)}</div>${jsonCard('Sealed Evidence Package',d.evidence_package)}`;$('#back').onclick=adminJudgments}
