function connectorWorkbench(r){$('#view').innerHTML=`<button class="btn" id="back">← 返回 Connector</button>${jsonCard('Connector Onboarding',r)}<div class="card"><h3>受控操作</h3><div class="field"><label>Approval ID</label><input id="aid"></div><div class="field"><label>Canary Rollout %</label><input id="pct" type="number" min="0" max="100" value="5"></div><div class="actionbar"><button class="btn primary" id="activate">Activate</button><button class="btn danger" id="suspend">Suspend</button></div></div>`;$('#back').onclick=adminConnectors;$('#activate').onclick=async()=>{try{await api.request(`/internal/v1/supplier-connectors/${r.onboarding_id}/activate`,{method:'POST',headers:{'X-Approval-ID':$('#aid').value},body:{percent:Number($('#pct').value)}});notice('Connector 已激活');adminConnectors()}catch(e){notice(e.message,true)}};$('#suspend').onclick=()=>consoleSheet({title:'暂停 Connector',description:'高风险操作会保留审批与审计证据。',fields:[{id:'suspendReason',label:'暂停原因',value:'SLA_RISK'}],confirmLabel:'确认暂停',danger:true,onConfirm:async v=>{await api.request(`/internal/v1/supplier-connectors/${r.onboarding_id}/suspend`,{method:'POST',headers:{'X-Approval-ID':$('#aid').value},body:{reason:v.suspendReason}});notice('Connector 已暂停');adminConnectors()}})}
async function approvalsPage(){const d=unwrap(await api.request('/internal/v1/approvals'));const arr=d.items||[];$('#view').innerHTML=`<div class="split"><div class="card"><h3>创建高风险审批</h3><div class="field"><label>Operation</label><select id="op"><option>COMPENSATION</option><option>SUPPLIER_LIABILITY</option><option>BANK_DEBIT</option><option>RISK_FINALIZATION</option><option>CONNECTOR_ACTIVATION</option><option>CONNECTOR_SUSPENSION</option><option>RULE_VERSION_RELEASE</option><option>HIGH_RISK_ADMIN_WORKFLOW</option></select></div><div class="field"><label>Subject Type</label><input id="st" value="RISK_EVENT"></div><div class="field"><label>Subject ID</label><input id="sid"></div><button id="req" class="btn primary">创建</button></div><div class="card"><h3>审批</h3><div class="field"><label>Approval ID</label><input id="aid"></div><div class="field"><label>备注</label><input id="note"></div><button id="approve" class="btn primary">批准</button></div></div><h2>Approval Queue</h2>${table(arr)}`;$('#req').onclick=async()=>{try{await api.request('/internal/v1/approvals',{method:'POST',body:{operation_type:$('#op').value,subject_type:$('#st').value,subject_id:$('#sid').value,payload:{source:'Sprint1T Workbench'}}});approvalsPage()}catch(e){notice(e.message,true)}};$('#approve').onclick=async()=>{try{await api.request(`/internal/v1/approvals/${$('#aid').value}/approve`,{method:'POST',body:{note:$('#note').value}});approvalsPage()}catch(e){notice(e.message,true)}}}


