async function recoveryControl(){const d=unwrap(await api.request('/internal/v1/recovery/control-plane/cases?limit=100'));const arr=d.items||[];$('#view').innerHTML=`<div class="section-head"><h2>Recovery SLA & Human Ops Control</h2><span>Supplier Fact 只读 · SLA 自动升级 · 责任队列 · Evidence Gate</span></div>${metrics({open:arr.filter(x=>x.state!=='RESOLVED').length,sla_breached:arr.filter(x=>x.acknowledge_breached||x.resolution_breached).length,escalated:arr.filter(x=>(x.current_escalation_level||0)>0).length,unassigned:arr.filter(x=>!x.assigned_to&&x.state!=='RESOLVED').length})}<div class="actionbar"><button class="btn primary" id="slaTick">运行 SLA Engine</button><button class="btn" id="showPolicies">查看 SLA / Queue</button></div>${table(arr,true)}`;bindRows(arr,r=>recoveryCase(r.operational_case_id));$('#slaTick').onclick=async()=>{await api.request('/internal/v1/recovery/control-plane/sla/tick',{method:'POST'});recoveryControl()};$('#showPolicies').onclick=async()=>{const p=unwrap(await api.request('/internal/v1/recovery/control-plane/sla-policies'));const q=unwrap(await api.request('/internal/v1/recovery/control-plane/queues'));$('#view').innerHTML=`<button class="btn" id="back">← 返回</button><h2>Recovery SLA Policies</h2>${table(p.items||[])}<h2>Ops Queues / On-call</h2>${table(q.items||[])}`;$('#back').onclick=recoveryControl}}
async function recoveryCase(id){const d=unwrap(await api.request(`/internal/v1/recovery/control-plane/cases/${encodeURIComponent(id)}`));$('#view').innerHTML=`<button class="btn" id="back">← 返回 Recovery Control</button><div class="split">${jsonCard('Operational Case',{case_id:d.operational_case_id,vertical:d.vertical,state:d.state,severity:d.severity,queue_key:d.queue_key,assigned_to:d.assigned_to,age_seconds:d.age_seconds,escalation_level:d.current_escalation_level,acknowledge_breached:d.acknowledge_breached,resolution_breached:d.resolution_breached})}${jsonCard('SLA / Playbook',{sla_policy_id:d.sla_policy_id,acknowledge_due_at:d.acknowledge_due_at,resolution_due_at:d.resolution_due_at,next_escalation_at:d.next_escalation_at,playbook_key:d.playbook_key,required_evidence_kinds:d.required_evidence_kinds,closure_evidence_status:d.closure_evidence_status})}</div><div class="split">${jsonCard('Supplier External Fact',{supplier_status:d.supplier_status,adapter_key:d.adapter_key,external_operation_id:d.external_operation_id,mutable_by_admin:d.supplier_fact_mutable_by_admin})}${jsonCard('Resolution Evidence Gate',d.closure_evidence_requirement)}</div><div class="actionbar"><button class="btn primary" id="assign">分配负责人</button><button class="btn" id="ack">确认已接手</button><button class="btn" id="transfer">责任转派</button><button class="btn" id="closeCase">Evidence Gate 关闭</button></div><h2>Human Ops Playbook</h2>${table(d.playbook||[])}<h2>Operational Timeline</h2>${table(d.operational_events||[])}${jsonCard('Hash Chain Verification',d.chain_verification)}<h2>Command Ledger</h2>${table(d.command_ledger)}<h2>Supplier Evidence Chain</h2>${table(d.evidence_chain)}`;$('#back').onclick=recoveryControl;$('#assign').onclick=()=>consoleSheet({title:'分配负责人',fields:[{id:'assignee',label:'负责人'},{id:'assignNote',label:'备注（可空）',required:false}],confirmLabel:'确认分配',onConfirm:async v=>{await api.request(`/internal/v1/recovery/control-plane/cases/${id}/assign`,{method:'POST',body:{assigned_to:v.assignee,note:v.assignNote||null}});recoveryCase(id)}});$('#ack').onclick=async()=>{await api.request(`/internal/v1/recovery/control-plane/cases/${id}/acknowledge`,{method:'POST'});recoveryCase(id)};$('#transfer').onclick=()=>consoleSheet({title:'责任转派',fields:[{id:'targetQueue',label:'目标 Queue',value:'recovery_p0'},{id:'targetOwner',label:'负责人（可空）',required:false}],confirmLabel:'确认转派',onConfirm:async v=>{await api.request(`/internal/v1/recovery/control-plane/cases/${id}/transfer`,{method:'POST',body:{queue_key:v.targetQueue,assigned_to:v.targetOwner||null,note:'manual responsibility transfer'}});recoveryCase(id)}});$('#closeCase').onclick=async()=>{await api.request(`/internal/v1/recovery/control-plane/cases/${id}/close`,{method:'POST',body:{note:'closed through evidence gate'}});recoveryCase(id)}}

