async function recoveryReleases(){const [c,b,m,d]=await Promise.all(['/internal/v1/recovery/releases/config-versions','/internal/v1/recovery/releases/environment-bindings','/internal/v1/recovery/releases/manifests','/internal/v1/recovery/releases/drift'].map(x=>api.request(x).then(unwrap)));const cs=c.items||[],bs=b.items||[],ms=m.items||[],ds=d.items||[];$('#view').innerHTML=`<div class="section-head"><h2>Recovery Production Release Governance</h2><span>Immutable Config · DEV → STAGING → PROD · Dry-run · Evidence · Maker-Checker · Rollback · Drift</span></div>${metrics({config_versions:cs.length,prod_bindings:bs.filter(x=>x.environment==='PROD').length,pending_releases:ms.filter(x=>!['PROMOTED','ROLLED_BACK'].includes(x.state)).length,drifted:bs.filter(x=>x.drift_status==='DRIFTED').length})}<div class="card"><h3>Production Promotion Rule</h3><p>PROD promotion requires immutable config hashes, source environment binding match, dry-run PASS, staging evidence and maker-checker approval. Rollback changes environment bindings only; Supplier Fact and completed transactions remain unchanged.</p></div><h2>Environment Bindings</h2>${table(bs)}<h2>Release Manifests</h2>${table(ms,true)}<h2>Immutable Config Versions</h2>${table(cs)}<h2>Config Drift Assessments</h2>${table(ds)}`;bindRows(ms,async r=>{const x=unwrap(await api.request(`/internal/v1/recovery/releases/manifests/${r.release_manifest_id}`));$('#view').innerHTML=`<button class="btn" id="back">← 返回 Release Governance</button>${jsonCard('Release Manifest',x)}<h2>Release Events</h2>${table(x.events||[])}`;$('#back').onclick=recoveryReleases})}


async function recoveryRuntimeSafety(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/safety/status?environment=PROD'));const a=r.latest_assessment||{},c=r.control||{},recs=r.rollback_recommendations||[];$('#view').innerHTML=`<div class="section-head"><h2>Recovery Runtime Release Safety</h2><span>Continuous Observability · SLO Burn Rate · Error Budget · Release Correlation · Promotion Freeze</span></div>${metrics({state:a.state||'NO_DATA',short_burn:a.short_burn_rate??0,long_burn:a.long_burn_rate??0,promotion_frozen:c.promotion_frozen?'YES':'NO'})}<div class="card"><h3>Automated Safety Boundary</h3><p>Burn-rate breach may automatically freeze further promotion and create a governed rollback recommendation. It never directly rolls back Supplier transactions or mutates Supplier Fact.</p></div>${jsonCard('Latest Safety Assessment',a)}<h2>Rollback Recommendations</h2>${table(recs,true)}`;bindRows(recs,x=>{if(x.state==='OPEN')consoleConfirm({title:'确认回滚建议',description:'这里只确认已查看建议，不会擅自执行数据库回滚。',confirmLabel:'确认已查看',onConfirm:async()=>{await api.request(`/internal/v1/recovery/runtime/rollback-recommendations/${x.rollback_recommendation_id}/acknowledge`,{method:'POST'});recoveryRuntimeSafety()}})})}
async function recoveryTelemetryGovernance(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/telemetry/status?environment=PROD'));const p=r.active_policy||{},q=r.latest_quality||{},c=r.latest_correlation||{},src=r.sources||[],safe=r.release_safety||{};$('#view').innerHTML=`<div class="section-head"><h2>Runtime Telemetry Governance</h2><span>Source Provenance · Freshness/Quality Gate · Multi-Window SLO · Incident Correlation</span></div>${metrics({sources:src.length,quality:q.state||'NO_DATA',correlation:c.confidence||'NO_DATA',promotion_frozen:safe.control?.promotion_frozen?'YES':'NO'})}<div class="card"><h3>Evidence Before Action</h3><p>Once governed telemetry is configured, legacy safety assessment cannot bypass source provenance and quality gates. Insufficient telemetry can only produce OBSERVE_ONLY; it cannot freeze PROD or recommend rollback.</p></div><h2>Telemetry Sources</h2>${table(src)}${jsonCard('Active Multi-Window SLO Policy',p)}${jsonCard('Latest Telemetry Quality Assessment',q)}${jsonCard('Latest Release / Deployment / Incident Correlation',c)}`}


async function recoveryIdentityLifecycle(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/identity-lifecycle/status?environment=PROD'));$('#view').innerHTML=`<div class="section-head"><h2>Runtime Identity Lifecycle + Security Incidents</h2><span>Key Rotation · Revocation · Quarantine · Trust Cache Invalidation</span></div>${metrics({cache_epoch:r.trust_cache_epoch,active_incidents:r.active_security_incidents?.length||0,recent_revocations:r.recent_revocations?.length||0})}<div class="card"><h3>Security Boundary</h3><p>Compromised workload/collector identities are immediately suspended or revoked. Their historical telemetry remains auditable but is excluded from source quorum and automatic release-safety decisions. Resume requires separate remediation; containment never silently reactivates an identity.</p></div><h2>Active Security Incidents</h2>${table(r.active_security_incidents||[])}<h2>Recent Revocations</h2>${table(r.recent_revocations||[])}`}

async function recoveryIdentityReissuance(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/identity-reissuance/status?environment=PROD'));$('#view').innerHTML=`<div class="section-head"><h2>Runtime Identity Re-Issuance + Credential Recovery</h2><span>Replacement Identity · Attestation · Maker-Checker · Lineage · Tombstone</span></div>${metrics({requests:r.reissuance_requests?.length||0,lineage:r.lineage?.length||0,tombstones:r.tombstones?.length||0,cache_epoch:r.trust_cache_epoch||0})}<div class="card"><h3>Recovery Boundary</h3><p>A revoked identity is terminal and cannot be reactivated. Recovery creates a new replacement identity only after verified attestation and distinct approval. The predecessor remains tombstoned and auditable forever.</p></div><h2>Re-Issuance Requests</h2>${table(r.reissuance_requests||[])}<h2>Identity Lineage</h2>${table(r.lineage||[])}<h2>Revoked Identity Tombstones</h2>${table(r.tombstones||[])}`}
async function recoveryCredentialAuthority(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/credential-authority/status?environment=PROD'));$('#view').innerHTML=`<div class="section-head"><h2>Credential Issuance Authority + Hardware Trust Federation</h2><span>Trust Root · Issuer · Policy Version · Verifier Quorum · Credential Lineage · Revocation Sync</span></div>${metrics({trust_roots:r.trust_roots?.length||0,issuers:r.issuers?.length||0,policies:r.policies?.length||0,credentials:r.credential_issuances?.length||0,revocation_syncs:r.revocation_syncs?.length||0})}<div class="card"><h3>Production Admission Boundary</h3><p>Attestation PASS does not equal PROD eligibility. Runtime identities require an active governed credential issued under an active policy, trusted issuer/root and verifier quorum. Revocation removes eligibility immediately but never mutates Supplier Fact or completed transactions.</p></div><h2>Hardware Trust Roots</h2>${table(r.trust_roots||[])}<h2>Credential Issuers</h2>${table(r.issuers||[])}<h2>Attestation Policies</h2>${table(r.policies||[])}<h2>Credential Issuances</h2>${table(r.credential_issuances||[])}<h2>Revocation Synchronization</h2>${table(r.revocation_syncs||[])}`}


async function externalTrust(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/external-trust/status?environment=PROD'));const cp=r.public_checkpoint||{};$('#view').innerHTML=`<div class="section-head"><h2>External Trust Witness + Multi-Region Consensus</h2><span>Merkle Proof · Witness Co-sign · Split-View Detection · Fail-Safe Admission</span></div>${metrics({tree_size:cp.tree_size||0,witnesses:r.witnesses?.length||0,region_replicas:r.region_replicas?.length||0,policies:r.policies?.length||0,recent_decisions:r.recent_decisions?.length||0})}<div class="card"><h3>Fail-Safe Boundary</h3><p>Multi-region admission requires consistent fresh credential state, identical witnessed checkpoint, witness quorum, and local federated admission. Any regional disagreement is SPLIT_VIEW_DETECTED and fails closed; majority vote cannot override a conflicting revocation view.</p></div>${jsonCard('Witnessed Merkle Checkpoint',cp)}<h2>External Witnesses</h2>${table(r.witnesses||[])}<h2>Region Trust Replicas</h2>${table(r.region_replicas||[])}<h2>Admission Policies</h2>${table(r.policies||[])}<h2>Recent Consensus Decisions</h2>${table(r.recent_decisions||[])}`;}


async function forecastServingGovernance(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/trust-plane/readiness/enterprise-risk/forecast-serving/status?environment=PROD'));const b=(r.bindings||[])[0]||{},i=(r.runtime_identities||[])[0]||{},a=(r.attestations||[])[0]||{},c=(r.safety_controls||[])[0]||{};$('#view').innerHTML=`<div class="section-head"><h2>Forecast Serving Attestation</h2><span>Deployment Provenance · Runtime Model Identity · Loaded Artifact Digest · Fail-Safe Serving Gate</span></div>${metrics({deployment:b.state||'NONE',runtime_identity:i.state||'NONE',serving_attestation:a.attestation_state||'NONE',serving_control:c.control_state||'NONE'})}<div class="card"><h3>Runtime serving boundary</h3><p>4P proves which signed model artifact is eligible for promotion. 4Q proves that the runtime actually loaded that exact artifact/build and is serving it under the governed model identity. Any digest, build-hash or runtime-fingerprint mismatch blocks the model from Forecast until a new verified serving attestation is recorded.</p></div><h2>Artifact Deployment Bindings</h2>${table(r.bindings||[])}<h2>Runtime Model Identities</h2>${table(r.runtime_identities||[])}<h2>Serving Attestations</h2>${table(r.attestations||[])}<h2>Serving Safety Controls</h2>${table(r.safety_controls||[])}`;}

async function recoveryFederatedTrust(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/federated-trust/status?environment=PROD'));const cp=r.transparency_checkpoint||{};$('#view').innerHTML=`<div class="section-head"><h2>Federated Trust + Credential Status Distribution</h2><span>Certificate Transparency · CRL/OCSP-like Freshness · Issuer Fan-out · Runtime Admission</span></div>${metrics({federations:r.federations?.length||0,admission_policies:r.admission_policies?.length||0,recent_decisions:r.recent_admission_decisions?.length||0,issuer_incidents:r.issuer_compromises?.length||0,transparency_tree_size:cp.tree_size||0})}<div class="card"><h3>Federated Admission Boundary</h3><p>Credential validity is distributed as fresh, append-only verifiable status. A signed runtime identity is admitted only when credential status is GOOD and fresh, the root is in an active trust federation, and the applicable cluster policy allows it. Issuer compromise fans out revocation immediately; these controls never mutate Supplier Fact or completed transactions.</p></div><h2>Trust Federations</h2>${table(r.federations||[])}<h2>Admission Policies</h2>${table(r.admission_policies||[])}<h2>Recent Admission Decisions</h2>${table(r.recent_admission_decisions||[])}<h2>Issuer Compromise Fan-out</h2>${table(r.issuer_compromises||[])}${jsonCard('Transparency Checkpoint',cp)}`}

async function recoveryTelemetryTrust(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/trust/status?environment=PROD'));const p=r.active_policy||{},t=r.latest_trust_assessment||{},ids=r.identities||[],tel=r.telemetry_governance||{};$('#view').innerHTML=`<div class="section-head"><h2>Runtime Telemetry Trust Chain</h2><span>Signed Runtime Identity · Anti-Replay · Clock Skew · Source Quorum · Incident Automation Policy</span></div>${metrics({identities:ids.length,trust:t.state||'NO_DATA',evidence:t.evidence_level||'NO_DATA',verified_sources:t.verified_source_count||0,promotion_frozen:tel.release_safety?.control?.promotion_frozen?'YES':'NO'})}<div class="card"><h3>Automation Evidence Boundary</h3><p>Only signed workload + collector identity envelopes that pass anti-replay, clock-skew and source-quorum checks may authorize automatic release safety actions. Insufficient evidence is HUMAN_REVIEW_ONLY. Telemetry trust never mutates Supplier Fact or completed transactions.</p></div><h2>Runtime / Collector Identities</h2>${table(ids)}${jsonCard('Active Incident Automation Policy',p)}${jsonCard('Latest Telemetry Trust Assessment',t)}`}


async function forecastModelStatistics(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/trust-plane/readiness/enterprise-risk/forecast-model-statistics/status?environment=PROD'));const p=r.active_policy||{},pr=(r.probations||[])[0]||{},rb=(r.rollback_events||[])[0]||{};$('#view').innerHTML=`<div class="section-head"><h2>Forecast Statistical Promotion + Automated Rollback</h2><span>Significance · Effect Size · Stability · Segment Consistency · Probation</span></div>${metrics({policy_state:p.state||'NONE',alpha:p.significance_alpha??0,min_effect_pct:p.minimum_effect_size_pct??0,stability_evals:p.stability_evaluations_required??0,probation:pr.state||'NONE',rollback_to:rb.to_model_version_id||'NONE'})}<div class="card"><h3>Promotion safety boundary</h3><p>Promotion requires statistical significance, minimum effect size, rolling stability across both horizons and required segments. A promoted Challenger enters probation first; real-world degradation rolls the model role back to the previous Champion without rewriting historical forecasts or business facts.</p></div><h2>Active Policy</h2>${table(p&&p.forecast_promotion_policy_id?[p]:[])}<h2>Promotion Probations</h2>${table(r.probations||[])}<h2>Automated Rollbacks</h2>${table(r.rollback_events||[])}`;}

