async function forecastArtifactGovernance(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/trust-plane/readiness/enterprise-risk/forecast-artifacts/status?environment=PROD'));const p=r.active_policy||{},a=(r.artifacts||[])[0]||{},b=(r.bindings||[])[0]||{},i=(r.integrity||[])[0]||{};$('#view').innerHTML=`<div class="section-head"><h2>Forecast Artifact Supply-Chain Governance</h2><span>Artifact Digest · SBOM · Signed Build Attestation · Promotion Binding · Tamper Detection</span></div>${metrics({policy_state:p.state||'NONE',latest_artifact:a.state||'NONE',package_format:a.package_format||'—',integrity_state:i.integrity_state||'NONE',promotion_binding:b.binding_state||'NONE'})}<div class="card"><h3>Production artifact boundary</h3><p>4O proves the build is reproducible; 4P proves the exact package entering 4L/4M is the artifact produced by that governed build. An active 4P policy requires artifact digest + SBOM/provenance + verified signed build attestation + fresh integrity PASS + promotion binding. Any later digest/build-hash mismatch removes promotion eligibility without rewriting historical artifact evidence.</p></div><h2>Model Artifact Registry</h2>${table(r.artifacts||[])}<h2>Promotion Bindings</h2>${table(r.bindings||[])}<h2>Integrity Assessments</h2>${table(r.integrity||[])}`;}

async function route(){notice('');const path=location.hash.slice(1)||nav[0].route;document.querySelectorAll('.nav a').forEach(a=>a.classList.toggle('active',a.dataset.route===path));const item=routeCatalog.find(x=>x.route===path)||nav[0];$('#pageTitle').textContent=item.label;try{if(item.custom==='supplierOrders')return supplierOrders();if(item.custom==='supplierRisks')return supplierRisks();if(item.custom==='supplierLiabilities')return supplierLiabilities();if(item.custom==='adminJudgments')return adminJudgments();if(item.custom==='adminSettlement')return adminSettlement();if(item.custom==='adminConnectors')return adminConnectors();if(item.custom==='approvals')return approvalsPage();if(item.custom==='recoveryControl')return recoveryControl();if(item.custom==='recoveryExperiments')return recoveryExperiments();if(item.custom==='recoveryLearning')return recoveryLearning();if(item.custom==='recoveryDataGovernance')return recoveryDataGovernance();if(item.custom==='recoveryLearningIncidents')return recoveryLearningIncidents();if(item.custom==='recoveryReleases')return recoveryReleases();if(item.custom==='recoveryRuntimeSafety')return recoveryRuntimeSafety();if(item.custom==='recoveryTelemetryGovernance')return recoveryTelemetryGovernance();if(item.custom==='recoveryTelemetryTrust')return recoveryTelemetryTrust();if(item.custom==='recoveryIdentityLifecycle')return recoveryIdentityLifecycle();if(item.custom==='recoveryIdentityReissuance')return recoveryIdentityReissuance();if(item.custom==='recoveryCredentialAuthority')return recoveryCredentialAuthority();if(item.custom==='recoveryFederatedTrust')return recoveryFederatedTrust();if(item.custom==='externalTrust')return externalTrust();if(item.custom==='trustGossip')return trustGossip();if(item.custom==='trustPlaneDR')return trustPlaneDR();if(item.custom==='trustChaosReadiness')return trustChaosReadiness();if(item.custom==='continuousChaosWaivers')return continuousChaosWaivers();if(item.custom==='waiverExposureDebt')return waiverExposureDebt();if(item.custom==='exceptionDebtBurndown')return exceptionDebtBurndown();if(item.custom==='enterpriseRiskPortfolio')return enterpriseRiskPortfolio();if(item.custom==='enterpriseRiskAppetite')return enterpriseRiskAppetite();if(item.custom==='enterpriseRiskForecast')return enterpriseRiskForecast();if(item.custom==='riskForecastCalibration')return riskForecastCalibration();if(item.custom==='forecastModelGovernance')return forecastModelGovernance();if(item.custom==='forecastModelStatistics')return forecastModelStatistics();if(item.custom==='forecastDriftGovernance')return forecastDriftGovernance();if(item.custom==='forecastTrainingGovernance')return forecastTrainingGovernance();if(item.custom==='forecastArtifactGovernance')return forecastArtifactGovernance();if(item.custom==='forecastServingGovernance')return forecastServingGovernance();if(item.custom==='audit')return auditPage();return generic(item)}catch(e){notice(e.message,true)}}
const ADMIN_TERM_MAP={'暂无数据':'当前没有需要处理的业务记录','Evidence':'证据','Remediation':'整改记录','Recent Economics Evidence':'近期经营分析','Forecast':'预测','Risk':'风险','Supplier':'供应商','Orders':'订单','Refunds':'退款','Settlement':'结算','Status':'状态','State':'状态'};
function adminProductizeView(route,label){if(config.actorType!=='GO_ADMIN')return;const view=$('#view');if(!view)return;if(!view.querySelector('.productized-admin-head'))view.insertAdjacentHTML('afterbegin',`<section class="productized-admin-head"><div><h2>${esc(label||'运营模块')}</h2><p>当前状态 → 核心指标 → 业务对象 → 待办异常 → 可执行动作 → 状态与审计</p></div><span class="status">运营工作台</span></section>`);view.querySelectorAll('.empty').forEach(x=>{x.outerHTML=adminEmpty('当前没有需要处理的业务记录')});view.querySelectorAll('pre.mono.pre').forEach(pre=>{const d=pre.closest('details');if(!d){const wrap=document.createElement('details');wrap.className='card tech-diagnostics';wrap.innerHTML='<summary>技术信息 / 原始数据</summary>';pre.replaceWith(wrap);wrap.appendChild(pre)}});view.querySelectorAll('h2,h3').forEach(h=>{const map={Requirements:'需求',Prebook:'预订前核验','Prebook Revalidation':'预订前重新核验','Order Handoffs':'订单交接','责任事件':'供应商责任事件',Liabilities:'赔付责任','保障资金记录':'保障资金记录',Subscriptions:'订阅状态','有效订单证据':'有效订单证据',Invoices:'账单',Waivers:'豁免申请',Credential:'身份凭证'};if(map[h.textContent.trim()])h.textContent=map[h.textContent.trim()]});if(!view.querySelector('.admin-ops-bar'))view.insertAdjacentHTML('beforeend',adminOpsBar());bindAdminOps()}
function installAdminProductizationObserver(){if(config.actorType!=='GO_ADMIN')return;const v=$('#view');if(!v)return;const ob=new MutationObserver(()=>{const item=routeCatalog.find(x=>x.route===(location.hash.slice(1)||nav[0].route))||nav[0];adminProductizeView(item.route,item.label)});ob.observe(v,{childList:true,subtree:true});adminProductizeView(nav[0].route,nav[0].label)}
(async()=>{try{me=unwrap(await api.me());if(config.actorType&&me.actor_type!==config.actorType)throw new Error('WRONG_ACTOR');shell();queueMicrotask(installAdminProductizationObserver)}catch{loginView()}})();
async function recoveryDataGovernance(){const [q,m,b,k,z]=await Promise.all(['/internal/v1/recovery/learning/data-quality','/internal/v1/recovery/learning/supplier-mappings','/internal/v1/recovery/learning/privacy-budgets','/internal/v1/recovery/learning/kill-switches','/internal/v1/recovery/learning/quarantine'].map(x=>api.request(x).then(unwrap)));const qs=q.items||[],ks=k.items||[];$('#view').innerHTML=`<div class="section-head"><h2>Recovery Data Governance</h2><span>Data Quality · Supplier Identity · Privacy Budget · Learning Kill Switch</span></div>${metrics({quality_pass:qs.filter(x=>x.quality_state==='PASS').length,quarantined:qs.filter(x=>x.quality_state==='QUARANTINED').length,kill_switches:ks.filter(x=>x.enabled).length,privacy_scopes:(b.items||[]).length})}<div class="actionbar"><button class="btn primary" id="dqTick">Run Data Quality Gate</button><button class="btn" id="globalStop">Emergency: Baseline Only</button><button class="btn" id="incidentControl">Open Incident Change Control</button></div><h2>Data Quality</h2>${table(qs)}<h2>Supplier Identity Mapping</h2>${table(m.items||[])}<h2>Privacy Budget</h2>${table(b.items||[])}<h2>Learning Kill Switches</h2>${table(ks)}<h2>Quarantine</h2>${table(z.items||[])}`;$('#dqTick').onclick=async()=>{await api.request('/internal/v1/recovery/learning/data-quality/tick',{method:'POST'});recoveryDataGovernance()};$('#globalStop').onclick=()=>consoleSheet({title:'Emergency: Baseline Only',description:'进入全局基线保护状态，需要原因和后续治理证据。',fields:[{id:'baselineReason',label:'Incident 原因'}],confirmLabel:'进入 Baseline Only',danger:true,onConfirm:async v=>{await api.request('/internal/v1/recovery/learning/incidents',{method:'POST',body:{scope_type:'GLOBAL',scope_key:'*',severity:'SEV1',reason:v.baselineReason}});location.hash='/recovery-learning-incidents'}});$('#incidentControl').onclick=()=>{location.hash='/recovery-learning-incidents'}}


async function trustPlaneDR(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/trust-plane/status?environment=PROD'));$('#view').innerHTML=`<div class="section-head"><h2>Witness Independence + Trust Plane Disaster Recovery</h2><span>Operator Diversity · Failure Domains · Cross-Operator Gossip · Archive/Rebuild · DR Drill</span></div>${metrics({operators:r.operators?.length||0,active_policies:r.active_policies?.length||0,recent_assessments:r.recent_assessments?.length||0,disasters:r.disasters?.length||0})}<div class="card"><h3>Independence Boundary</h3><p>Witness quorum is counted by independent operators and failure domains, not by raw process count. The same operator, cloud or key authority cannot manufacture quorum. Open Region/Provider trust-plane disasters fail safe until every affected region has a verified archive rebuild under independent witness governance.</p></div><h2>Witness Operators</h2>${table(r.operators||[])}<h2>Independence Policies</h2>${table(r.active_policies||[])}<h2>Recent Independence Assessments</h2>${table(r.recent_assessments||[])}<h2>Trust Plane Disasters / Drills</h2>${table(r.disasters||[])}`}
