async function riskForecastCalibration(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/trust-plane/readiness/enterprise-risk/forecast-calibration/status?environment=PROD'));const a=(r.accuracy_assessments||[])[0]||{},c=(r.calibrations||[])[0]||{},g=r.runtime_governance||{};$('#view').innerHTML=`<div class="section-head"><h2>Risk Forecast Calibration + Accuracy</h2><span>Predicted vs Actual · MAE/Brier · 24h/7d Calibration · Capacity Drift · Conservative Baseline</span></div>${metrics({runtime_mode:g.mode||'LEGACY',accuracy_state:a.accuracy_state||'NO_DATA',horizon_hours:a.horizon_hours||0,sample_count:a.sample_count||0,mae_points:a.mae_points??0,brier_score:a.brier_score??0,capacity_drift_pct:a.mean_capacity_drift_pct??0,calibration_error_pct:c.calibration_error_pct??0})}<div class="card"><h3>Forecast safety boundary</h3><p>Forecasts are evaluated against observed outcomes and capacity allocation drift. Accuracy degradation automatically activates a conservative baseline; it changes forecast strategy only and never changes supplier, payment or existing risk facts.</p></div><h2>Model Versions</h2>${table(r.models||[])}<h2>Accuracy Assessments</h2>${table(r.accuracy_assessments||[])}<h2>24h / 7d Calibration</h2>${table(r.calibrations||[])}<h2>Safety Controls</h2>${table(r.safety_controls||[])}`}

async function enterpriseRiskAppetite(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/trust-plane/readiness/enterprise-risk/appetite/status?environment=PROD'));const a=r.latest_stress_assessment||{},f=(r.stress_freezes||[])[0]||{},e=r.appetite||{};$('#view').innerHTML=`<div class="section-head"><h2>Enterprise Risk Appetite + Stress Testing</h2><span>Scenario Stress · Headroom · Capacity Buffer · Sensitivity · Preemptive Freeze</span></div>${metrics({stress_state:a.assessment_state||'NO_DATA',current_exposure:a.current_exposure_points??0,stressed_exposure:a.stressed_exposure_points??0,headroom:a.headroom_points??0,capacity_buffer_pct:a.capacity_buffer_pct??0,sensitivity_pct:a.sensitivity_pct??0,preemptive_freeze:f.state||'NONE'})}<div class="card"><h3>Forward-looking boundary</h3><p>Portfolio PASS is not sufficient. Board-approved risk appetite requires enough stressed headroom and capacity buffer under cloud-provider, identity-root, region and release-control shocks. Stress breach freezes new waivers and executive risk acceptance before real exposure materializes.</p></div><h2>Risk Appetite Envelope</h2>${table(e&&e.risk_appetite_envelope_id?[e]:[])}<h2>Stress Scenarios</h2>${table(r.scenarios||[])}<h2>Latest Stress Assessment</h2>${table(a&&a.stress_assessment_id?[a]:[])}<h2>Preemptive Freezes</h2>${table(r.stress_freezes||[])}`};

async function forecastModelGovernance(){const r=unwrap(await api.request('/internal/v1/recovery/runtime/trust-plane/readiness/enterprise-risk/forecast-model-governance/status?environment=PROD'));$('#view').innerHTML=`<div class="section-head"><h2>Forecast Champion / Challenger Governance</h2><span>Backtest · Shadow · Horizon/Segment Gate · Promotion</span></div>${metrics({champions:(r.roles||[]).filter(x=>x.role==='CHAMPION'&&x.state==='ACTIVE').length,challengers:(r.roles||[]).filter(x=>x.role==='CHALLENGER'&&x.state==='ACTIVE').length,promotions:(r.decisions||[]).filter(x=>x.decision==='PROMOTED').length,blocked:(r.decisions||[]).filter(x=>x.decision==='BLOCKED').length})}<div class="card"><h3>Promotion boundary</h3><p>Challenger never affects runtime before promotion. Both 24h and 7d shadow gates must pass and safety metrics must not degrade. Promotion switches the Champion role only; Supplier Fact and existing risk facts remain unchanged.</p></div><h2>Model Roles</h2>${table(r.roles||[])}<h2>Promotion Decisions</h2>${table(r.decisions||[])}`;}

