async function adminIdentityQueue(){const rows=unwrap(await api.request('/internal/v1/go-identity/credentials'));$('#view').innerHTML=`<div class="section-head"><h2>GO Identity 凭证队列</h2><span>Evidence · Deterministic Rule · Review · Suspend/Revoke</span></div><div class="actionbar"><button class="btn primary" id="identityTick">运行周期复核</button></div>${table(rows||[],true)}`;bindRows(rows||[],r=>adminIdentityCredential(r));$('#identityTick').onclick=async()=>{try{const x=unwrap(await api.request('/internal/v1/go-identity/revalidation/tick',{method:'POST'}));notice(`复核完成：${x.processed}`);adminIdentityQueue()}catch(e){notice(e.message,true)}}}
function adminIdentityCredential(r){$('#view').innerHTML=`<button class="btn" id="back">← 返回 凭证队列</button>${jsonCard('Credential',r)}<div class="card"><h3>提交验证证据</h3><div class="field"><label>证据类型</label><input id="eType" value="EMPLOYMENT_ROSTER"></div><div class="field"><label>来源类型</label><input id="eSource" value="HOTEL_HR_API"></div><div class="field"><label>来源参考</label><input id="eRef"></div><div class="field"><label>置信度</label><input id="eConfidence" type="number" value="9000"></div><button class="btn primary" id="eSubmit">按规则验证</button></div><div class="actionbar"><button class="btn" id="toReview">进入复核</button><button class="btn danger" id="toSuspend">暂停</button><button class="btn danger" id="toRevoke">撤销</button></div>`;$('#back').onclick=adminIdentityQueue;$('#eSubmit').onclick=async()=>{try{await api.request(`/internal/v1/go-identity/credentials/${r.credential_id}/evidence`,{method:'POST',body:{evidence_type:$('#eType').value,source_type:$('#eSource').value,source_reference:$('#eRef').value,subject_match:true,confidence_bps:Number($('#eConfidence').value)}});notice('证据已进入确定性规则');adminIdentityQueue()}catch(e){notice(e.message,true)}};for(const [id,state] of [['toReview','REVIEW'],['toSuspend','SUSPENDED'],['toRevoke','REVOKED']])$("#"+id).onclick=async()=>{try{await api.request(`/internal/v1/go-identity/credentials/${r.credential_id}/transition`,{method:'POST',body:{state,reason:'ADMIN_EVIDENCE_REVIEW'}});adminIdentityQueue()}catch(e){notice(e.message,true)}}}

