function supplierGoOfferRequirement(r){currentSupplierRoute='/go-offer';$('#view').innerHTML=`<button class="btn" id="back">← 返回 GO Offer</button>${supplierObjectCard('需求详情',r)}<div class="card"><h3>人工报价</h3><div class="field"><label>报价金额（分）</label><input id="goAmount" type="number"></div><div class="field"><label>币种</label><input id="goCurrency" value="CNY"></div><button class="btn primary" id="goQuote">提交报价</button></div><div class="card"><h3>提交前重新核验</h3><div class="field"><label>预订预核验编号</label><input id="goPrebook"></div><div class="field"><label>酒店确认参考号</label><input id="goConfirm"></div><button class="btn primary" id="goRevalidate">确认可售、价格与条款</button></div>`;$('#back').onclick=supplierGoOffer;$('#goQuote').onclick=async()=>{try{await api.request(`/v1/supplier/go-offer/requirements/${r.go_offer_requirement_id}/quotes`,{method:'POST',body:{amount_minor:Number($('#goAmount').value),currency:$('#goCurrency').value,validity_minutes:30,package:{},conditions:{}}});notice('报价已提交');supplierGoOffer()}catch(e){notice(e.message,true)}};$('#goRevalidate').onclick=async()=>{try{await api.request(`/v1/supplier/go-offer/prebooks/${$('#goPrebook').value}/revalidate`,{method:'POST',body:{available:true,amount_minor:Number($('#goAmount').value),currency:$('#goCurrency').value,conditions_changed:false,supplier_confirmation_reference:$('#goConfirm').value}});notice('可售、价格与条款已重新核验');supplierGoOffer()}catch(e){notice(e.message,true)}}}
