const PROMOTIONS=[['PROMOTION_DAILY_DEAL','天天特价','基础促销'],['PROMOTION_EARLY_BOOKING','提前预订','场景促销'],['PROMOTION_LONG_STAY','连住优惠','场景促销'],['PROMOTION_MULTI_ROOM','多间优惠','场景促销'],['PROMOTION_LAST_MINUTE','今夜优惠','场景促销'],['PROMOTION_NEW_GUEST','新客优惠','客群促销'],['PROMOTION_LOCAL_GUEST','本地客优惠','客群促销'],['PROMOTION_LIMITED_TIME','限时优惠','场景促销']];
async function supplierPromotions(){
  const p=await supplierFirstProperty();if(!p){$('#view').innerHTML=supplierStructuredShell('/marketing',supplierStructuredEmpty('/marketing'),{'启用促销':0,'基础促销':0,'场景促销':0,'待核验':0});return}
  const g=unwrap(await api.request(`/v1/supplier/properties/${encodeURIComponent(p.property_id)}/product-graph`)),policies=g.policies||[],promo=policies.filter(x=>String(x.policy_type||'').startsWith('PROMOTION_'));
  const cards=PROMOTIONS.map(([key,name,group])=>{const row=promo.find(x=>x.policy_type===key),r=policyRule(row);return `<article class="card promo-card"><div class="section-head"><div><h3>${esc(name)}</h3><span>${esc(group)}</span></div><span class="status">${r.enabled?'已启用':'未启用'}</span></div><p>${r.enabled?`优惠 ${Number(r.discount_bps||0)/100}% · ${esc(r.start_date||'长期')} 至 ${esc(r.end_date||'长期')}`:'酒店自主决定是否开启，不影响 GO 推荐排名。'}</p><button class="btn" data-promo="${key}" data-name="${esc(name)}">设置</button></article>`}).join('');
  $('#view').innerHTML=supplierStructuredShell('/marketing',`<section class="card structured-section"><div><h3>自主促销原则</h3><p>促销只改变酒店自己授权的价格/条件；不购买推荐、不虚构“同行提升”，最终效果只使用酒店自己的真实数据评估。</p></div><span class="status">酒店自主</span></section><div class="grid promo-grid">${cards}</div>`,{'启用促销':promo.filter(x=>policyRule(x).enabled).length,'基础促销':promo.filter(x=>x.policy_type==='PROMOTION_DAILY_DEAL'&&policyRule(x).enabled).length,'场景促销':promo.filter(x=>x.policy_type!=='PROMOTION_DAILY_DEAL'&&policyRule(x).enabled).length,'待核验':promo.filter(x=>!x.updated_at).length});
  document.querySelectorAll('[data-promo]').forEach(b=>b.onclick=()=>supplierPromotionEditor(p,b.dataset.promo,b.dataset.name,promo.find(x=>x.policy_type===b.dataset.promo)));
}
function supplierPromotionEditor(p,key,name,row){const r=policyRule(row),today=new Date().toISOString().slice(0,10);$('#view').innerHTML=supplierStructuredShell('/marketing',`<button class="btn" id="promoBack">← 返回自主促销</button><section class="card"><h3>${esc(name)}</h3><div class="business-form-grid"><label class="business-field"><span>启用状态</span><select id="promoEnabled"><option value="YES" ${r.enabled?'selected':''}>启用</option><option value="NO" ${!r.enabled?'selected':''}>停用</option></select></label><label class="business-field"><span>优惠幅度（%）</span><input id="promoDiscount" type="number" min="0" max="100" step="0.1" value="${Number(r.discount_bps||0)/100}"></label><label class="business-field"><span>开始日期</span><input id="promoStart" type="date" value="${esc(r.start_date||today)}"></label><label class="business-field"><span>结束日期</span><input id="promoEnd" type="date" value="${esc(r.end_date||today)}"></label><label class="business-field"><span>适用房型编号</span><input id="promoRooms" value="${esc((r.room_type_ids||[]).join(','))}" placeholder="留空=全部房型"></label><label class="business-field"><span>最少提前/连住/间数</span><input id="promoThreshold" type="number" min="0" value="${Number(r.threshold||0)}"></label></div><button class="btn primary" id="promoSave">保存促销</button></section>`,{'启用促销':'—','基础促销':'—','场景促销':'—','待核验':'—'});$('#promoBack').onclick=supplierPromotions;$('#promoSave').onclick=async()=>{try{const rule={enabled:$('#promoEnabled').value==='YES',discount_bps:Math.round(Number($('#promoDiscount').value||0)*100),start_date:$('#promoStart').value,end_date:$('#promoEnd').value,room_type_ids:$('#promoRooms').value.split(',').map(x=>x.trim()).filter(Boolean),threshold:Number($('#promoThreshold').value||0),source:'SUPPLIER_CONSOLE',recommendation_pool_unchanged:true};await api.request(`/v1/supplier/properties/${encodeURIComponent(p.property_id)}/policies`,{method:'PUT',body:{policy_type:key,rule}});notice('促销已保存');supplierPromotions()}catch(e){notice(e.message,true)}}}

async function supplierAiMarketing(){
  const p=await supplierFirstProperty();if(!p){$('#view').innerHTML=supplierStructuredShell('/ai-marketing',supplierStructuredEmpty('/ai-marketing'),{'建议':0,'证据':0,'可执行':0,'需确认':0});return}
  const [g,snap,value]=await Promise.all([api.request(`/v1/supplier/properties/${encodeURIComponent(p.property_id)}/product-graph`).then(unwrap),api.request(`/v1/supplier/properties/${encodeURIComponent(p.property_id)}/operating-snapshot`).then(unwrap),api.request(`/v1/hotels/${encodeURIComponent(p.property_id)}/value-layers`).then(unwrap)]);
  const rates=g.rate_plans||[],rooms=g.room_types||[],ari=snap.ari_date_overrides||[],promo=(g.policies||[]).filter(x=>String(x.policy_type||'').startsWith('PROMOTION_')&&policyRule(x).enabled),suggestions=[];
  if(!rooms.length)suggestions.push(['先完善房型','当前没有可销售的物理房型事实。','/rooms','房型数据']);
  if(rooms.length&&!rates.length)suggestions.push(['建立标准价格计划','已有房型但还没有价格计划，无法形成稳定的房态房价管理。','/rates','房型 + 价格计划']);
  if(rates.length&&ari.length<7)suggestions.push(['补齐未来房态房价','当前按日期房态房价覆盖较少，建议先补齐未来至少 7 天；AI 不会自动改价。','/rates','ARI 日期覆盖']);
  if(!value.official_direct_value)suggestions.push(['配置官方权益','当前没有 GO 官方直连权益，可优先考虑早餐、延迟退房或有房升房等低成本高感知权益。','/benefits','官方权益']);
  if(!promo.length&&rates.length)suggestions.push(['评估一个轻量自主促销','当前未启用自主促销，可由酒店按实际淡日选择提前订、连住或今夜优惠；不建议无差别降价。','/marketing','促销状态']);
  if(!suggestions.length)suggestions.push(['保持当前配置并观察真实数据','房型、价格计划、日期房态、官方权益和促销均已有配置；先积累真实订单数据再判断是否调整。','/growth-data','现有经营事实']);
  const cards=suggestions.map((x,i)=>`<article class="card"><div class="section-head"><div><h3>${esc(x[0])}</h3><span>建议 ${i+1}</span></div><span class="status">需酒店确认</span></div><p>${esc(x[1])}</p><p class="muted">依据：${esc(x[3])}</p><a class="btn primary" href="#${x[2]}">去设置</a></article>`).join('');
  $('#view').innerHTML=supplierStructuredShell('/ai-marketing',`<section class="card structured-section"><div><h3>AI 操作边界</h3><p>GO AI 只生成可解释建议；不会自动修改价格、库存、促销或权益。任何业务变更都由酒店确认后执行。</p></div><span class="status">AI 不自动执行</span></section>${cards}`,{'建议':suggestions.length,'证据':rooms.length+rates.length+ari.length+(value.official_direct_value?1:0),'可执行':suggestions.length,'需确认':suggestions.length});
}

async function supplierGrowthData(){
  const p=await supplierFirstProperty();if(!p){$('#view').innerHTML=supplierStructuredShell('/growth-data',supplierStructuredEmpty('/growth-data'),{'订单':0,'价格计划':0,'房态日期':0,'促销':0});return}
  const reqs=[api.request(`/v1/supplier/properties/${encodeURIComponent(p.property_id)}/product-graph`).then(unwrap),api.request(`/v1/supplier/properties/${encodeURIComponent(p.property_id)}/operating-snapshot`).then(unwrap),api.request('/v1/supplier/orders').then(unwrap),api.request(`/v1/supplier/direct-value/hotels/${encodeURIComponent(p.property_id)}/economics`).then(unwrap).catch(()=>[])];
  const [g,snap,ordersRaw,econ]=await Promise.all(reqs),orders=ordersRaw.items||ordersRaw||[],promo=(g.policies||[]).filter(x=>String(x.policy_type||'').startsWith('PROMOTION_')&&policyRule(x).enabled),ari=snap.ari_date_overrides||[],rates=g.rate_plans||[];
  const completed=orders.filter(x=>/COMPLETED|CHECKED_OUT|FULFILLED/.test(String(x.state||x.status||''))).length,cancelled=orders.filter(x=>/CANCEL/.test(String(x.state||x.status||''))).length;
  const body=`<section class="card structured-section"><div><h3>数据口径</h3><p>这里只展示 GO 已经记录的酒店自身事实。没有真实样本时，不显示“转化率提升”“同行流量增长”等推测数字。</p></div><span class="status">真实数据</span></section><div class="grid structured-metrics"><div class="card structured-metric"><div class="metric-label">订单总数</div><div class="metric-value">${orders.length}</div><div class="metric-sub">当前 GO 可见订单</div></div><div class="card structured-metric"><div class="metric-label">已履约</div><div class="metric-value">${completed}</div><div class="metric-sub">以订单事实为准</div></div><div class="card structured-metric"><div class="metric-label">已取消</div><div class="metric-value">${cancelled}</div><div class="metric-sub">不推断原因</div></div><div class="card structured-metric"><div class="metric-label">渠道经济证据</div><div class="metric-value">${Array.isArray(econ)?econ.length:0}</div><div class="metric-sub">仅已运行的真实/模拟记录</div></div></div><h3>近期订单事实</h3>${orders.length?table(orders.slice(0,20),false,'订单'):supplierStructuredEmpty('/growth-data','订单数据')}<h3>渠道经济证据</h3>${Array.isArray(econ)&&econ.length?table(econ.slice(0,20),false,'渠道经济证据'):'<section class="card structured-empty"><div><h3>暂无渠道经济证据</h3><p>没有足够数据时不展示虚构效果。</p></div></section>'}`;
  $('#view').innerHTML=supplierStructuredShell('/growth-data',body,{'订单':orders.length,'价格计划':rates.length,'房态日期':ari.length,'促销':promo.length});
}


