  $('#view').innerHTML=`<section class="card structured-section"><div><h3>全生态统一运营</h3><p>酒店、机票、铁路、接送用车、租车、景点门票与体验共用同一套订单履约、交易状态、异常分流和治理能力。正常流程由系统自动运行，人只处理决策与异常。</p></div><span class="status">小团队运营</span></section>${lifecycle}<div class="grid">${cards.map(x=>{const c=byV[x[3]]||{},d=depthByV[x[3]]||{};return adminHubLink(x[0],x[1],`${x[2]} ${d.rc20_pass_state?`RC20：${d.rc20_pass_state==='PASS'?'已通过':'Staging E2E 待验收'}；`:''}${c.required_stage_count?`生命周期 ${c.productized_stage_count}/${c.required_stage_count}；`:''}正式外部供给按 Provider 上线状态单独验收。`)}).join('')}</div><section class="card"><h3>跨生态共享入口</h3><div class="structured-actions"><a class="btn" href="#/supplier-registry">供应商</a><a class="btn" href="#/orders">订单履约</a><a class="btn" href="#/transaction-evidence">交易状态与证据</a><a class="btn primary" href="#/exception-center">异常中心</a></div></section>`;
